\label{as:fullcolumn1}
   Suppose that
   \begin{align*}
       \mathop{\mathrm{rank}}\nolimits(CE) = e.
   \end{align*}

\label{markov}
 ~ From the true system $(A,B,C,D)$, the Markov parameter matrix required to recover the input-output mapping is denoted as $G^*$ and defined by 
    \begin{equation}\label{gstar}
        G^* = [D~CB~ CAB~ \dots ~ CA^{k-2}B].
    \end{equation}
    Note that the size of $G^*$ depends on $k$; however, we omit the explicit dependence on $k$ in the notation for simplicity.

\label{maxnorm}
 Define a filtration {$\mathcal{F}_t = \bm{\sigma}\{x_0, x_1, \dots, x_t\}$.}
    There exists $\eta >0$ such that
  {   $x_0 = (x_{0,i})_{i=1}^n$ and $w_t = (w_{t,i})_{i=1}^e$ satisfies $\max_{i\in\{1,\dots,n\}}\|x_{0,i}\|_{\psi_2} \leq \eta$ and $\max_{i\in\{1,\dots,e\}}\|w_{t,i}\;|\;\mathcal{F}_t\|_{\psi_2} \leq \eta$ for all $t \geq 0$.}

\label{alphabetabound}
    Suppose that Assumptions \ref{stability} and \ref{maxnorm} hold.  Let the control inputs $\{u_t\}_{t=0}^{T+k-2}$ be independent with $u_t\sim N(0, \sigma^2 I_m)$. Then,  given $\delta\in(0,1]$, when $T= \Omega(\log(\frac{1}{\delta }))$,
    \begin{align*}
    \sum_{t\in \mathcal{T}} \|\alpha_t^{(s)}\|_2 +\|\beta_t\|_2 \le  \mathcal{O}\Bigr({\rho^{s}}\|C\|_2 MT\Bigr)
\end{align*}
holds with probability at least $1-\delta$, where $M:= \frac{\eta {\sqrt{n}}+ \eta\sqrt{e}\|E\|_2+\sigma \sqrt{m} \|B\|_2}{1-\rho}$.

\label{as:fullcolumn}
  Suppose that 
     \begin{align*}
         \mathop{\mathrm{Im}}\nolimits(CE)\cap
\mathop{\mathrm{Im}}\nolimits([CAE\ \dots\ CA^{s-1}E])
=\{0\}.
     \end{align*}

\label{K_lowerbound}
Let the control inputs $\{u_t\}_{t=0}^{T+k-2}$ be independent with $u_t \sim \mathcal{N}(0, \sigma^2 I_m)$. Consider a fixed matrix $K \in \mathbb{R}^{e \times mk}$. Then, given $\delta \in (0,1]$, when 
\begin{align*}
    T = \Omega\left( \frac{k}{(1-p)^{s-1}} \log\left(\frac{1}{\delta}\right) \right),
\end{align*}
it holds that 
\begin{align}\label{KU_T}
    \sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2 \ge \frac{(1-p)^{s-1}\sigma}{4} \sqrt{\frac{2}{\pi}} \|K\|_F T
\end{align}
with probability at least $1-\delta$.

\label{lem:psi_lower_bound}
Let the control inputs $\{u_t\}_{t=0}^{T+k-2}$ be independent with $u_t \sim \mathcal{N}(0, \sigma^2 I_m)$. For $K \in \mathbb{R}^{e \times mk}$ and $\tilde Q_s \in \mathbb{R}^{e\times e(s-1)}$, consider a function 
\begin{equation}\label{f_T_K_Q}
\begin{split}
    f_T(K,\tilde Q_s):=  &\sum_{t\in\mathcal{T}}\|K \mathbf{U}_t^{(k)}  + \tilde Q_s\mathbf{\tilde W}_t^{(s)}\|_2\\&\hspace{0mm}-2 \min\Bigl\{\|K \mathbf{U}_t^{(k)}  + \tilde Q_s\mathbf{\tilde W}_t^{(s)}\|_2,\|w_{t-1}\|_2\Bigr\}
    \end{split}
\end{equation}
where $\mathbf{\tilde W}_t^{(s)} := [w_{t-2}^T ~ \dots ~ w_{t-s}^T]^T$. 
Given $h>0$ and  $\delta \in (0, 1]$, when
\begin{equation}\label{eq:T_condition_psi}
\begin{split}
    T = \Omega\biggr(& \frac{k}{(1-p)^{s-1}} \log\left(\frac{1}{\delta}\right) \\&+ \frac{\eta^2 e \log(1/\delta)}{ h^2 \rho^{2s}} \log\left(\frac{1}{\delta} \cdot\frac{\eta^2 e \log(1/\delta)}{  \rho^{2s}  h^2} \right) \biggr),
    \end{split}
\end{equation}
the infimum $\Psi_T(K) := \inf_{\tilde Q_s} f_T(K, \tilde Q_s)$ satisfies
\begin{align}\label{psi_lowerbound}
    \Psi_T(K) \ge \frac{(1-2p)(1-p)^{s-1}\sigma}{4} \sqrt{\frac{2}{\pi}} \|K\|_F T -  \rho^s h T.
\end{align}
 with probability at least $1-\delta$.

\label{lem:universallowerbound}
 Let the control inputs $\{u_t\}_{t=0}^{T+k-2}$ be independent with $u_t \sim \mathcal{N}(0, \sigma^2 I_m)$.  Define $c_* := \frac{(1-2p)(1-p)^{s-1}\sigma}{4} \sqrt{\frac{2}{\pi}}$ and 
 $R:= \frac{4\rho^s h}{c_*}$ for $h>0$. Let $\mathcal{S}_R := \{K \in \mathbb{R}^{e \times mk} : \|K\|_F = R\}$ denote the Frobenius sphere of radius $R$. Given $\delta\in(0,1]$, when 
 \begin{align}\label{final_timebound}
    &T=\tilde \Omega\left(\frac{e  m k^2s }{(1-p)^{s-1}}  +\frac{\eta^2 e \cdot  (emks)^2 }{ \rho^{2s}h^2 } \right),
\end{align}
we have
 \begin{align}\label{goal}
    \Psi_T(K) \ge \frac{c_*}{4} RT,\quad \forall K\in \mathcal{S}_R 
    \end{align}
    with probability at least $1-\delta$.

\label{thm:main}
Let the control inputs $\{u_t\}_{t=0}^{T+k-2}$ be independent with $u_t \sim \mathcal{N}(0, \sigma^2 I_m)$. Consider a minimizer $(\hat H, \hat J)$ to the constrained $\ell_2$-norm estimator \eqref{l2est}, and define $\hat K := \hat H G^* - \hat J$. Given $\delta \in (0, 1]$, when
\begin{align}\label{final_timebound2}
    T = \tilde{\Omega}\bigg( \frac{e m k^2 s}{(1-p)^{s-1}} + \frac{\eta^2 e\cdot (e m k s)^2}{\rho^{2s} (\|\hat H\|_2+\|H^*\|_2)^2} \bigg),
\end{align}
then  the estimation error satisfies
\begin{align}
\|\hat K\|_F = \mathcal{O}\bigg(\Big(\frac{\rho}{1-p}\Big)^s\frac{(1-p)(\|\hat H\|_2 + \|H^*\|_2)(1+\|C\|_2 M)}{(1-2p) \sigma} \bigg)  
\end{align}
with probability at least $1-\delta$, where $M$ is defined in Lemma \ref{alphabetabound}.

For any scalar $\alpha \ge 1$ and $a, b \ge 0$, we have $\min\{\alpha a, b\} \le \alpha \min\{a, b\}$. Applying this inequality to $f_T$ yields $f_T(\alpha K, \alpha Q) \ge \alpha f_T(K, Q)$ for all $\alpha \ge 1$. Taking the infimum over $Q$ on both sides provides
\begin{equation}\label{alphalower}
\begin{split}
    \Psi_T (\alpha K ) &= \inf_{\tilde Q_s} f_T(\alpha K , \tilde Q_s)= \inf_{ Q} f_T(\alpha K , \alpha  Q)\\& \ge \alpha \inf_Qf_T(K,Q) = \alpha \Psi_T(K)
    \end{split}
\end{equation}
for all $\alpha\ge 1$.
Setting $h := \|\hat H\|_2 +\|H^*\|_2> 0$ and $R := \frac{4\rho^s (\|\hat H\|_2+\|H^*\|_2)}{c_*}$, Lemma \ref{lem:universallowerbound} guarantees that when $T$ satisfies \eqref{final_timebound2},
the universal lower bound \eqref{goal} holds
with probability at least $1-\delta$.

Now, for any matrix $\relax K$ satisfying $\|\relax K\|_F \ge R$, consider the scaling parameter $\alpha := \|\relax K\|_F / R \ge 1$. Since $\|\relax K / \alpha\|_F = R$, sequentially applying \eqref{alphalower} and \eqref{goal} yields
\begin{align}\label{psitkbar}
    \Psi_T(\relax K) = \Psi_T\Big( \alpha \frac{\relax K}{\alpha} \Big) \ge \alpha \Psi_T\Big( \frac{\relax K}{\alpha} \Big) \ge \alpha \frac{c_*}{4}  RT = \frac{c_*}{4}  \|\relax K\|_F T.
\end{align}
with probability at least $1-\delta$.

Now, we evaluate the norm of $\hat K = \hat H G^*-\hat J$ under two exhaustive cases:
\begin{itemize}[leftmargin=0.4cm]
    \item \textbf{Case 1 ($\|\hat K\|_F < R$):} By definition of $R$, we directly have
    \begin{align}\label{case1}
    \|\hat K\|_F < \frac{4\rho^s  (\|\hat H\|_2+\|H^*\|_2)}{c_*} = \mathcal{O}\left(\frac{\rho^s(\|\hat H\|_2+\|H^*\|_2)}{(1-2p)(1-p)^{s-1} \sigma}\right).
\end{align}
    \item \textbf{Case 2 ($\|\hat K\|_F \ge R$):} By the equivalence between \eqref{l2est} and \eqref{expanded2}, there exist matrices $\hat Q_s,\hat H, \hat J$ such that $(\hat K, \hat Q_s, \hat H, \hat J)$ is a minimizer of \eqref{expanded2}. Furthermore, under Assumptions \ref{as:fullcolumn1} and \ref{as:fullcolumn}, there exist matrices $H^*, J^*$ such that $(0, Q_s^*,  H^*,  J^*)$ is feasible for \eqref{expanded2} by Lemma \ref{assumptionequivalence}. Applying the triangle inequality, we obtain
    \begin{align*}
      & \sum_{t\in\mathcal{T}}  \left\| \hat K \mathbf{U}_t^{(k)} +\hat Q_s \mathbf{W}_t^{(s)}\right\|_2- \|\hat H\|_2 \bigg(\sum_{t\in\mathcal{T}}\|\alpha_t^{(s)}\|_2 + \|\beta_t\|_2\bigg)\\
        &\le\sum_{t\in\mathcal{T}}  \left\| \hat K \mathbf{U}_t^{(k)} +\hat Q_s \mathbf{W}_t^{(s)} + \hat H\alpha_t^{(s)} + \hat H\beta_t\right\|_2 \\&\le \sum_{t\in\mathcal{T}} \left\|  Q_s^* \mathbf{W}_t^{(s)} +  H^*\alpha_t^{(s)} +  H^*\beta_t\right\|_2 \\&\le \sum_{t\in\mathcal{T}}\| Q_s^* \mathbf{W}_t^{(s)}\|_2 + \| H^*\|_2 \bigg(\sum_{t\in\mathcal{T}}\|\alpha_t^{(s)}\|_2 + \|\beta_t\|_2\bigg),
    \end{align*}
    which implies that \begin{align*}\Psi_T(\hat K)&\le \sum_{t\in\mathcal{T}}  \| \hat K \mathbf{U}_t^{(k)} +\hat Q_s \mathbf{W}_t^{(s)}\|_2-\| Q_s^* \mathbf{W}_t^{(s)}\|_2\\&\le (\|\hat H\|_2 + \|H^*\|_2)\bigg(\sum_{t\in\mathcal{T}}\|\alpha_t^{(s)}\|_2 + \|\beta_t\|_2\bigg).\end{align*} Applying Lemma \ref{alphabetabound} to the right-hand side, while using the lower bound \eqref{psitkbar} evaluated at $\relax K = \hat K$ on the left-hand side, we arrive at
    \begin{align*}
        \frac{c_*}{4} \|\hat K\|_F T \le \Psi_T(\hat K) = \mathcal{O}\big( (\|\hat H\|_2 + \|H^*\|_2) \cdot \rho^s \|C\|_2 M T \big),
    \end{align*}
    which simplifies to
    \begin{align}\label{case2}
    \|\hat K\|_F  = \mathcal{O}\left(\frac{\rho^s (\|\hat H\|_2 + \|H^*\|_2)}{(1-2p)(1-p)^{s-1} \sigma}\cdot \|C\|_2 M\right)
\end{align}
with  probability at least $1-\delta$. 
\end{itemize}
Combining \eqref{case1} and \eqref{case2}

completes the proof.

\label{rem:filter_scaling}
If $\|\hat H\|_2$ or $\|H^*\|_2$ is exceptionally small, the time bound $T$ in \eqref{final_timebound2} increases significantly. This issue can be readily mitigated by enforcing a lower-bound constraint $\|H\|_2 \ge 1$ in the optimization problem \eqref{l2est}, which leaves the relative estimation error invariant. 
The only exception occurs when $CE$ is square and invertible ($s=1$), where $H = (CE)^{-1}$ is unique and imposing $\|H\|_2 \ge 1$ could induce infeasibility if $\|(CE)^{-1}\|_2 < 1$. In other cases where $H$ is non-unique, the set of valid left-inverses is unbounded, guaranteeing the existence of a feasible $H$ satisfying $\|H\|_2 \ge 1$. Imposing this lower-bound constraint prevents $\|\hat H\|_2 + \|H^*\|_2$ from approaching zero, effectively treating the $\|\hat H\|_2 + \|H^*\|_2$ factor in \eqref{final_timebound2} as a constant bounded below by $2$ to ensure a stable time bound.

Note that $\|\|x_0\|_2 \|_{\psi_2} \leq \eta{\sqrt{n}}, \|\|w_t\|_2\|_{\psi_2} \leq \eta{\sqrt{e}}, $ and $\|\|u_t\|_2\|_{\psi_2} \leq \sigma\sqrt{m}$  follow from Assumption \ref{maxnorm} and the Gaussianity of $u_t$. 
In turn, using the system dynamics \eqref{sysd} yields
\begin{align*}
  &  \|\|x_t\|_2\|_{\psi_2} = \Bigr\|\Bigr\|A^t x_0 + \sum_{i=0}^{t-1} (A^{t-1-i}Bu_i+A^{t-1-i}E w_{i})\Bigr\|_2 \Bigr\|_{\psi_2} \\& \leq \|A^t\|_2\cdot\|\|x_0\|_2\|_{\psi_2} \\&\hspace{5mm}+ \sum_{i=0}^{t-1} \|A^{t-1-i}\|_2 \bigr(\|B\|_2\cdot \|\|u_i\|_2\|_{\psi_2} +\|E\|_2 \|\|w_i\|_2\|_{\psi_2}\bigr) \\&\le \frac{\psi}{1-\rho} \cdot \left[\eta {\sqrt{n}}+ \eta\sqrt{e}\|E\|_2 + \sigma \sqrt{m} \|B\|_2\right]=\mathcal{O}(M)

    \addtocounter{equation}{1}\tag{\arabic{equation}}\label{xtsums}
\end{align*}
due to the triangle inequality and geometric sum with Assumption \ref{stability}.  We can sum up $\|x_t\|_2$ over $t=0, \dots, T-1$ to yield
\begin{align*}
        &\sum_{t=0}^{T-1} \|x_t\|_2 
        \le\sum_{i=0}^{\infty} \|A^i\|_2   \Bigr[\|x_0\|_{2} + \sum_{t=0}^{T-2} (\|Ew_t\|_{2} +  \|Bu_t\|_{2})\Bigr]\\&\hspace{2mm}\leq\frac{\psi}{1-\rho}\Bigr[\|x_0\|_{2} + \sum_{t=0}^{T-2} (\|E\|_2\|w_t\|_{2} +  \|B\|_2\|u_t\|_{2})\Bigr]:= X.
    \end{align*}
{Since the filtration $\mathcal{F}_t$ can alternatively be written as $\bm{\sigma}\{x_0, \{(u_\tau, w_\tau)\}_{\tau=0}^{t-1}\}$, sequentially applying the tower rule using $\mathcal{F}_t$ over $T$ steps establishes that $X-\mathbb{E}[X]$ is sub-Gaussian with norm $\mathcal{O}(M\sqrt{T})$.} 
   Then, Hoeffding's inequality yields
    \begin{align*}
        &\mathbb{P}\bigr( X-\mathbb{E}[X] \leq MT  \bigr) \geq 1-\exp(-\Omega(T)).\addtocounter{equation}{1}\tag{\arabic{equation}}\label{xt123}
    \end{align*}
Then, considering $\sum_{t=0}^{T-1} \|x_t\|_2 \le X$ and the expectation bound 
    $\mathbb{E}\bigr[\sum_{t=0}^{T-1} \|x_t\|_2\bigr]=\mathcal{O}(MT)$ from \eqref{xtsums} yields
    \begin{align*}
        \sum_{t=k-1}^{T+k-2} \|\beta_t\|_2= \sum_{t=0}^{T-1}\|CA^{k-1}x_t\|_2 = \mathcal{O}( \rho^{k-1}  \|C\|_2MT )\addtocounter{equation}{1}\tag{\arabic{equation}}\label{betatsum}
    \end{align*}
with probability at least $1-\frac{\delta}{2}$. Similarly, following  the same filtration argument, we have 
\begin{align*}
    \sum_{t=k-1}^{T+k-2}\|\alpha_t^{(s)}\|_2& \le\mathcal{O}\Big( \rho^s\|C\|_2\frac{\sum_{t=0}^{T+k-4}\|E\|_2\|w_t\|_2}{1-\rho}\Big) \\& = \mathcal{O}\Big( \rho^s \|C\|_2\frac{\eta\sqrt{n}\|E\|_2}{1-\rho}T\Big)\addtocounter{equation}{1}\tag{\arabic{equation}}\label{alphatsum}
\end{align*}
with probability at least $1-\frac{\delta}{2}$. We complete the proof by applying the union bound and summing up \eqref{betatsum} and \eqref{alphatsum}.

For a fixed realization of $\mathcal{T}_0$, define $f_K(\mathbf{U}) := \sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2$ for $\mathbf{U} = [u_0^T ~ u_1^T ~\dots u_{T+k-2}^T]^T \in \mathbb{R}^{m(T+k-1)}$.

First, we compute the Lipschitz constant of $f_K$. For any $\mathbf{U}, \mathbf{U}' \in \mathbb{R}^{m(T+k-1)}$, Cauchy-Schwarz inequality yields
\begin{align*}
    |f_{K}(\mathbf{U}) - f_{K}(\mathbf{U}')| 
    &\le \sum_{t\in\mathcal{T}_0} \|K (\mathbf{U}_t^{(k)} - (\mathbf{U}_t')^{(k)})\|_2 \\
    &\le \|K\|_F \sum_{t\in\mathcal{T}_0} \|\mathbf{U}_t^{(k)} - (\mathbf{U}_t')^{(k)}\|_2 \\
    &\le \|K\|_F \sqrt{|\mathcal{T}_0|} \sqrt{\sum_{t\in\mathcal{T}_0} \|\mathbf{U}_t^{(k)} - (\mathbf{U}_t')^{(k)}\|_2^2} \\
    &\le \|K\|_F \sqrt{|\mathcal{T}_0| k} \cdot \|\mathbf{U} - \mathbf{U}'\|_2.\addtocounter{equation}{1}\tag{\arabic{equation}}\label{KUlipschitz}
\end{align*}
Thus, $f_K$ has a Lipschitz constant of  $\|K\|_F \sqrt{|\mathcal{T}_0| k}$.


Gaussian concentration for Lipschitz functions (see Lemma 1 in \cite{kim2025bridging}) implies that
the sub-Gaussian norm of $\sum_{t\in\mathcal{T}_0} \|K\mathbf{U}_t^{(k)}\|_2-\mathbb{E}[\|K\mathbf{U}_t^{(k)}\|_2]$ is bounded by $\mathcal{O}(\sigma\|K\|_F\sqrt{|\mathcal{T}_0|k})$. Thus, we can write
\begin{align*}
   & \mathbb{P}\biggr( \sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2-\mathbb{E}[\|K \mathbf{U}_t^{(k)}\|_2] < -\frac{\sigma }{2}\sqrt{\frac{2}{\pi}}\|K\|_F|\mathcal{T}_0|\biggr)\\&\hspace{55mm}\le \exp\left(-\Omega\biggr(\frac{|\mathcal{T}_0| }{k}\right)\biggr).
\end{align*}
By $\sum_{t\in\mathcal{T}_0}\mathbb{E}[\|K \mathbf{U}_t^{(k)}\|_2]\ge \sigma\sqrt{\frac{2}{\pi}}\|K\|_F |\mathcal{T}_0|$, we arrive at
\begin{align*}
   & \mathbb{P}\biggr( \sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2<  \frac{\sigma }{2}\sqrt{\frac{2}{\pi}}\|K\|_F|\mathcal{T}_0|\biggr)\le \exp\left(-\Omega\biggr(\frac{|\mathcal{T}_0| }{k}\right)\biggr).
\end{align*}

We now bound the success probability using a union bound over two failure events:
\begin{enumerate}
    \item $E_1$: The event that $|\mathcal{T}_0| \ge \frac{(1-p)^{s-1}}{2} T$. By Chernoff's bound, $\mathbb{P}(E_1^c) \le \exp\left( -\frac{1}{8}(1-p)^{s-1} T \right)$. Setting this bound to $\le \delta/2$ requires $T = \Omega\big(\frac{1}{(1-p)^{s-1}} \log\left(\frac{1}{\delta}\right)\big)$.
    \item $E_2$: The event that $\sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2 \ge \frac{\sigma}{2}\sqrt{\frac{2}{\pi}}\|K\|_F |\mathcal{T}_0|$. Conditioned on $E_1$, we have $|\mathcal{T}_0| \ge \frac{(1-p)^{s-1}}{2} T$, leading to 
   $ \mathbb{P}(E_2^c \mid E_1) \le \exp\bigr( -\Omega\bigr(\frac{(1-p)^{s-1} T}{ k} \bigr)\bigr).$
    Setting this bound to $\le \delta/2$ requires $T =\Omega\big(\frac{ k}{(1-p)^{s-1}} \log\left(\frac{1}{\delta}\right)\big)$.
\end{enumerate}

Since $k\ge 1$, by taking $T =\Omega\big(\frac{ k}{(1-p)^{s-1}} \log\left(\frac{1}{\delta}\right)\big)$, the union bound guarantees that $E_1 \cap E_2$ holds with probability at least $1 - \mathbb{P}(E_1^c) - \mathbb{P}(E_2^c \mid E_1) \ge 1 - \delta$.

Finally, on the event $E_1 \cap E_2$, we substitute the lower bound for $|\mathcal{T}_0|$ in $E_1$ directly into the lower bound for $\sum_{t\in\mathcal{T}_0} \|K \mathbf{U}_t^{(k)}\|_2$ in $E_2$.
This completes the proof.

Define the $\sigma$-algebra $\mathcal{U} := \sigma(\{u_t\}_{t=0}^{T+k-2})$ and the growing filtration
\begin{align*}
    \mathcal{G}_{t-1} := \sigma\left( \mathcal{U}, \, \{w_{t-2}, w_{t-3}, \dots, w_0\} \right).
\end{align*}
Note that $\mathbf{U}_t^{(k)} \in \mathcal{G}_{t-1}$ and $\mathbf{\tilde W}_t^{(s)} \in \mathcal{G}_{t-1}$, which implies that $\|K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2$ is $\mathcal{G}_{t-1}$-measurable. Moreover, the indicator of new attack satisfies $\mathbb{P}(\xi_{t-1}=1 \mid \mathcal{G}_{t-1}) = p$.

Fix a threshold $B > 0$ and introduce the bounded, $\mathcal{G}_{t-1}$-measurable process $r_t := \min\big\{ \|K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2, B \big\}$. Define the high-probability noise-truncation event
\begin{align*}
    \mathcal{E}_B := \left\{ \max_{t\in\mathcal{T}} \|w_{t-1}\|_2 \le B \right\}.
\end{align*}
On event $\mathcal{E}_B$, we have $\min\{\|K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2, \|w_{t-1}\|_2\} \le \xi_{t-1} r_t$ since $\xi_{t-1}=0$ implies $w_{t-1}=0$. Substituting this into \eqref{f_T_K_Q} and centering around $p$ yields:
\begin{align*}
  &  f_T(K,\tilde Q_s) \ge
\sum_{t\in\mathcal{T}} \|K \mathbf{U}_t^{(k)}  + \tilde Q_s\mathbf{\tilde W}_t^{(s)}\|_2-2\sum_{t\in\mathcal{T}}\xi_{t-1}r_t\\

    &\ge (1-2p) \sum_{t\in\mathcal{T}} \|K \mathbf{U}_t^{(k)} + \tilde Q_s\mathbf{\tilde W}_t^{(s)}\|_2 - 2\sum_{t\in\mathcal{T}}(\xi_{t-1}-p) r_t.\addtocounter{equation}{1}\tag{\arabic{equation}}\label{1-2plower}
\end{align*}
Let $X_t := 2(\xi_{t-1}-p)r_t$. Then, since $\mathbb{E}[X_t \mid \mathcal{G}_{t-1}] = 0$, $\{X_t\}$ forms a martingale difference sequence with respect to $\{\mathcal{G}_{t-1}\}$.
Since $X_t \in [-2pr_t, \, 2(1-p)r_t]$ conditioned on $\mathcal{G}_{t-1}$, its conditional range is bounded by $2r_t \le 2B$. By Hoeffding's lemma for bounded variables, $\mathbb{E}\left[ e^{\lambda X_t} \mid \mathcal{G}_{t-1} \right] \le \exp\big( \frac{\lambda^2 B^2}{2} \big)$. Sequentially applying the tower rule using $\mathcal{G}_{t-1}$ over $T$ steps yields $\mathbb{E}\left[ \exp\left(\lambda \sum_{t\in\mathcal{T}} X_t\right) \right] \le \exp\big( \frac{\lambda^2 T B^2}{2} \big)$. By Hoeffding's inequality, we have
\begin{align}\label{eq:X_concentration}
    \mathbb{P}\left( \sum_{t\in\mathcal{T}} X_t \ge B \sqrt{2T \log\Big(\frac{3}{\delta}\Big)} \right) \le \frac{\delta}{3}.
\end{align}
Furthermore,
since $\|w_t\|_2$ is sub-Gaussian with parameter $\eta\sqrt{e}$, there exists a constant $c>0$ such that $\mathbb{P}(\|w_t\|_2 > B) \le 2\exp\big( -\frac{c B^2}{ \eta^2 e} \big)$. A union bound over all $T$ steps gives $\mathbb{P}(\mathcal{E}_B^c) \le 2T \exp\left( -\frac{c B^2}{ \eta^2 e} \right)$. Choosing 
\begin{align}\label{eq:B_choice}
    B =\sqrt{\frac{\eta^2 e}{c}  \log\left(\frac{6T}{\delta}\right) }
\end{align}
ensures that $\mathbb{P}(\mathcal{E}_B) \ge 1 - \frac{\delta}{3}$.

Finally, invoking Lemma \ref{K_lowerbound}, to guarantee that inequality \eqref{KU_T} holds with probability at least $1-\frac{\delta}{3}$, it suffices that $T = \Omega\left( \frac{k}{(1-p)^{s-1}} \log\left(\frac{3}{\delta}\right) \right)$.


Substituting \eqref{KU_T} and \eqref{eq:X_concentration} into \eqref{1-2plower}, we obtain
\begin{equation}\label{ft_lowerbound}
\begin{split}
  &  f_T(K, \tilde Q_s) 
    \\
    &\ge \frac{(1-2p)(1-p)^{s-1}\sigma}{4} \sqrt{\frac{2}{\pi}} \|K\|_F T - B \sqrt{2T \log\Big(\frac{3}{\delta}\Big)}.
    \end{split}
\end{equation}

We bound the last term as $B \sqrt{2T \log(\frac{3}{\delta})}\le  \rho^s h T$, which translates to $T \ge \frac{2 B^2 \log(3/\delta)}{  \rho^{2s} h^2}$. Substituting \eqref{eq:B_choice} for $B$ yields the sufficient condition on $T$ in \eqref{eq:T_condition_psi}. By applying a union bound across all events, the lower bound \eqref{ft_lowerbound} holds under \eqref{eq:T_condition_psi} with probability at least $1-\delta$.

Taking the infimum over $\tilde Q_s$ on both sides of \eqref{ft_lowerbound} yields \eqref{psi_lowerbound}, concluding the proof.

We establish the uniform lower bound via an $\epsilon$-net discretization argument over $\mathcal{S}_R$.
To this end, recall that $f_T(K, \tilde Q_s)$ can be equivalently represented using the identity $a - 2\min\{a, b\} = |a - b| - b$:
\begin{align*}
    &f_T(K, \tilde Q_s) \\&= \sum_{t\in\mathcal{T}} \Big| \|K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2 - \|w_{t-1}\|_2 \Big| - \|w_{t-1}\|_2.
\end{align*}
For any $K, \tilde K \in \mathcal{S}_R$ and any matrix $\tilde Q_s$, applying the reverse triangle inequality yields
\begin{align*}
    &|f_T(K, \tilde Q_s) - f_T(\tilde K, \tilde Q_s)| 
    \\&\le \sum_{t\in\mathcal{T}} \left| \|K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2 - \|\tilde K \mathbf{U}_t^{(k)} + \tilde Q_s \mathbf{\tilde W}_t^{(s)}\|_2 \right| \\
    &\le \sum_{t\in\mathcal{T}} \|(K - \tilde K) \mathbf{U}_t^{(k)}\|_2 \le \|K - \tilde K\|_F \sum_{t\in\mathcal{T}} \|\mathbf{U}_t^{(k)}\|_2.
\end{align*}
Rearranging and taking the infimum over $\tilde Q_s$ on both sides gives
\begin{align}\label{eq:psi_lipschitz}
    |\Psi_T(K) - \Psi_T(\tilde K)| \le \|K - \tilde K\|_F \sum_{t\in\mathcal{T}} \|\mathbf{U}_t^{(k)}\|_2.
\end{align}

Similar to the relationship \eqref{KUlipschitz}, the term $\sum_{t\in\mathcal{T}} \|\mathbf{U}_t^{(k)}\|_2$ is $\sqrt{Tk}$-Lipschitz. 
Since we have $\mathbb{E}[\|\mathbf{U}_t^{(k)}\|_2] \le \sigma \sqrt{mk}$ from $\mathbf{U}_t^{(k)} \sim \mathcal{N}(0, \sigma^2 I_{mk})$, 
Gaussian concentration for Lipschitz functions again implies that 
\begin{align*}
    \mathbb{P}\left( \sum_{t\in\mathcal{T}} \|\mathbf{U}_t^{(k)}\|_2 \le 2  \sigma \sqrt{mk}\cdot T \right) \ge 1 -  \exp(-\Omega(mT)).
\end{align*}
Thus, when $T=\Omega\bigr( \frac{1}{m}\log\left(\frac{2}{\delta}\right)\bigr)$, 
the inequality \eqref{eq:psi_lipschitz} extends to 
\begin{align}\label{Kinterbound}
    |\Psi_T(K) - \Psi_T(\tilde K)| \le 2 \sigma \sqrt{mk} \cdot T  \|K - \tilde K\|_F
\end{align}
with probability at least $1-\frac{\delta}{2}$.
To bound the right-hand side by $\frac{c_*}{2} R T$, we set the discretization grid resolution to
\begin{align*}
    \epsilon := \frac{c_* R}{4 \sigma \sqrt{mk}}.
\end{align*}
The covering number $N_\epsilon$ needed to cover $\mathcal{S}_R$ with $\epsilon$-balls in Frobenius norm satisfies
\begin{align*}
    N_\epsilon \le \left( 1 + \frac{2R}{\epsilon} \right)^{e m k} =\left( 1 +  \frac{16\sqrt{2\pi}\cdot \sqrt{mk}}{(1-2p)(1-p)^{s-1}} \right)^{e m k}.
\end{align*}

For each fixed grid point $\tilde K $ in the $\epsilon$-net, applying Lemma \ref{lem:psi_lower_bound} with failure probability $\frac{\delta}{2N_\epsilon}$ ensures that $\Psi_T(\tilde K) \ge c_* R T - \rho^s h T$ with probability at least $1 - \frac{\delta}{2N_\epsilon}$.

By a union bound over all $N_\epsilon$ grid points in the $\epsilon$-net, the pointwise lower bound holds simultaneously across the entire net with probability at least $1 - \frac{\delta}{2}$. Combining this with the  event in \eqref{Kinterbound} (which holds with probability at least $1 - \frac{\delta}{2}$), for any $K \in \mathcal{S}_R$, choosing a net point $\tilde K$ such that $\|K - \tilde K\|_F \le \epsilon$ yields
\begin{align*}
    \Psi_T(K) &\ge \Psi_T(\tilde K) - 2 T \sigma \sqrt{mk} \, \epsilon \\
    &\ge \left( c_* R T - \rho^s h T \right) - \frac{c_*}{2} R T = \frac{c_*}{4} R T
\end{align*}
with probability at least $1 - \delta$, where the last equality is from the definition of $R$.

To guarantee the union bound, we replace  $\delta $ in \eqref{eq:T_condition_psi} with  $\frac{\delta}{2N_\epsilon}$. Expanding the logarithm yields $\log(\frac{2N_\epsilon}{\delta}) = \mathcal{O}\big( e m k \log\big( \frac{mk}{(1-2p)(1-p)^{s-1}} \big) + \log(\frac{1}{\delta}) \big)=\mathcal{\tilde O}(emks)$, which leads to
the final time bound in \eqref{final_timebound}, hiding logarithmic factors. Note that  $T=\Omega\bigr( \frac{1}{m}\log\left(\frac{2}{\delta}\right)\bigr)$ required for \eqref{Kinterbound} is dominated by \eqref{final_timebound}. This completes the proof.
